def forward_hc_pre_from_prev(
    self,
    positions: torch.Tensor,
    state: mhc.HcState,
    input_ids: torch.Tensor,
    forward_batch: ForwardBatch,
    input_ids_global: torch.Tensor,
) -> mhc.HcState:
    """The layer's two hyper-connections, each collapsing with the previous one's
    pre-mix."""
    self._init_boundaries()
    stats_stream = None
    if mhc.use_stats_stream(self.hc_cfg, forward_batch, state.residual):
        stats_stream = self.hc_stats_stream
    # lever FG: this layer call's FFN-block graph plan (None: stock's body below, unchanged)
    fgp = fg.plan(self, state, forward_batch, stats_stream)

    def run_attn_hc(state: mhc.HcState) -> mhc.HcState:
        assert self.attn_hc is not None
        residual = state.residual
        quantized = [] if self.self_attn.accepts_mxfp8_swizzled_input() else None
        mhc.fork_stats_stream(stats_stream)
        x = hq.combine(self.attn_hc, state, quantized)  # lever HQ (gen_hq.py)
        precomputed = state.stats
        state.release()
        del state
        world_size = self.self_attn.attn_tp_size
        fuse_all_reduce_mhc = self._can_fuse_attn_mhc and _dv4.can_fuse_all_reduce(
            x.shape[0], self.hc_cfg.hidden
        )
        with self.self_attn.maybe_use_decode_attn_tp(forward_batch):
            y = self.self_attn(
                x=x,
                positions=positions,
                forward_batch=forward_batch,
                x_quant=quantized[0] if quantized else None,
                defer_all_reduce=fuse_all_reduce_mhc,
            )
        del x
        if fgp is not None:   # lever FG: stock's post, its mega boundary writing FG's static FFN inputs
            return fg.attn_post(
                fgp,
                self.attn_hc,
                y,
                residual,
                stats_stream=stats_stream,
                next=self.local_boundary,
                world_size=world_size,
                precomputed=precomputed,
            )
        return mhc.run_attn_post(
            self.attn_hc,
            y,
            residual,
            stats_stream=stats_stream,
            next=self.local_boundary,
            world_size=world_size,
            precomputed=precomputed,
        )

    def run_ffn_hc(state: mhc.HcState) -> mhc.HcState:
        assert self.ffn_hc is not None
        if fgp is not None:   # lever FG: the FFN block from this bucket's graphs (None: stock's body, state untouched)
            got = fg.ffn(fgp, self, state, forward_batch, input_ids, input_ids_global)
            if got is not None:
                return got
        residual = state.residual
        mhc.fork_stats_stream(stats_stream)
        x = mhc.combine(self.ffn_hc, state)
        precomputed = state.stats
        state.release()
        del state
        fuse_all_reduce_mhc = self._can_fuse_ffn_mhc and _dv4.can_fuse_all_reduce(
            x.shape[0], self.hc_cfg.hidden
        )
        from sglang.srt.models.deepseek_v4_prune import decode_rows

        with decode_rows(forward_batch):
            y = self._run_moe_ffn_dp_sync(
                x,
                forward_batch,
                input_ids=input_ids,
                input_ids_global=input_ids_global,
                return_moe_output=fuse_all_reduce_mhc,
            )
        del x
        return mhc.run_moe_post(
            self.ffn_hc,
            y,
            residual,
            stats_stream=stats_stream,
            next=self.next_boundary,
            world_size=self.mlp.tp_size,
            precomputed=precomputed,
        )

    return run_ffn_hc(run_attn_hc(state))


def mhc_mega_boundary_out(
    x,
    residual,
    pre,
    post,
    comb,
    fn,
    scale,
    base,
    weight,
    rms_eps,
    hc_eps,
    norm_eps,
    sinkhorn_iters,
    updated,
    normalized,
    next_pre,
    next_post,
    next_comb,
):
    """Update the residual, collapse with carried pre, and compute next stats.

    The collapse uses ``pre`` from the preceding sublayer, not the new pre
    produced from the updated residual. Preserve this DSv4.1 shifted ordering.
    Used by the opt-in SM10x prefill path. Before CUDA graph capture, warm up
    on the capture stream to initialize DeepGEMM's per-stream barriers.
    """
    rows, hidden = x.shape
    hc = residual.shape[1]
    # lever FG: stock's five outputs come in as arguments (FG's static buffers; same shapes / dtypes as stock's)
    deep_gemm.mega_mhc(
        x=x,
        residual=residual,
        shifted_prev_mix=pre.unsqueeze(-1),
        post_mix=post.unsqueeze(-1),
        comb_res_mix=comb,
        fn=fn,
        mix_scales=scale,
        mix_bases=base,
        hc_mult=hc,
        hc_norm_eps=rms_eps,
        hc_pre_eps=hc_eps,
        hc_post_scale=2.0,
        sinkhorn_eps=hc_eps,
        num_sinkhorn_iters=sinkhorn_iters,
        rmsnorm_weight=weight,
        rmsnorm_eps=norm_eps,
        rmsnorm_scale=1.0,
        new_residual=updated,
        new_prev_mix=next_pre,
        new_post_mix=next_post,
        new_comb_res_mix=next_comb,
        y_bf16=normalized,
    )
    return updated, normalized, (next_pre.squeeze(-1), next_post.squeeze(-1), next_comb)
